#!/usr/bin/env bash
#
# Shared host-side setup for the Ravenest admin CLI wrappers.
#
# install.sh copies this file and its callers into ${SERVER_PATH}/tools/.
# It never prints compose values, database URLs, or passwords.

set -uo pipefail

admin_load_compose_env() {
    SERVER_PATH="${SERVER_PATH:-$(cd -- "$SCRIPT_DIR/.." && pwd -P)}"
    COMPOSE_ENV="${COMPOSE_ENV:-${SERVER_PATH}/compose.env}"

    [ -f "$COMPOSE_ENV" ] || {
        printf 'error: compose env file not found: %s\n' "$COMPOSE_ENV" >&2
        exit 2
    }

    # Generated by install.sh; sourced only for safe compose values.
    set +u
    # shellcheck disable=SC1090
    . "$COMPOSE_ENV"
    set -u

    local base="${RAVENEST_COMPOSE_PATH:-${SERVER_PATH}/docker-compose.yml}"
    local overlay="${RAVENEST_COMPOSE_OVERLAY_PATH:-${SERVER_PATH}/docker-compose.bundled.yml}"

    [ -f "$base" ] || {
        printf 'error: compose file not found: %s\n' "$base" >&2
        exit 2
    }

    COMPOSE=(docker compose --env-file "$COMPOSE_ENV" -f "$base")
    if [ -n "${RAVENEST_DB_INIT_PATH:-}" ]; then
        [ -f "$overlay" ] || {
            printf 'error: bundled compose file not found: %s\n' "$overlay" >&2
            exit 2
        }
        COMPOSE+=(-f "$overlay")
    fi

    cd "$SERVER_PATH" || {
        printf 'error: cannot enter %s\n' "$SERVER_PATH" >&2
        exit 2
    }
}

admin_exec_in_app() {
    local binary="$1"
    shift

    command -v docker >/dev/null 2>&1 || {
        printf 'error: docker not found on PATH\n' >&2
        exit 2
    }
    docker info >/dev/null 2>&1 || {
        printf 'error: cannot reach the Docker daemon (check docker group/sudo)\n' >&2
        exit 2
    }
    docker inspect ravenest >/dev/null 2>&1 || {
        printf 'error: the ravenest container is not running; start the deployment first\n' >&2
        exit 2
    }

    exec "${COMPOSE[@]}" exec -T ravenest "$binary" "$@"
}
